/* =====================================================================
   engine.observability.js  —  Engine.Observability   (offline-plan §7-8)

   Ship the generated backend's telemetry to a LOCAL OpenTelemetry
   Collector — no SaaS account. The backend already builds per-request
   traces (engine.backend.js `span()` / `/debug/traces`); this adds a
   dependency-free OTLP/HTTP exporter (`src/otel.js`) that POSTs finished
   spans to `OTEL_EXPORTER_OTLP_ENDPOINT` (default http://localhost:4318),
   plus a ready collector config and a compose file.

       app → OTel SDK/exporter → local OTel Collector → traces/metrics/logs
           → .sovereign/otel/{traces,metrics,logs,evidence}.json

   §8: an optional self-hosted Sentry adapter (`src/sentry.js` wiring + a
   crash probe) for deep error capture — BLOCKED without a local Sentry,
   never marked unsupported. Hosted Sentry export stays credential-gated.

   window.Engine.Observability
     files()          -> { '/src/otel.js', '/otel-collector-config.yaml', … }
     sentryFiles()    -> { '/src/sentry.js', '/sentry/docker-compose.yml' }
     verify(opts?)    -> Promise<{ status, checks, reason?, need? }>
     analyze()        -> writes .sovereign/otel-evidence.json
   ===================================================================== */
(function () {
  'use strict';
  var Engine = window.Engine || (window.Engine = {});
  var S = function () { return Engine.Sovereign; };
  var FS = function () { return Engine.FS; };
  function has(p) { try { return !!(FS() && FS().isFile(p)); } catch (_) { return false; } }
  function adapters() { return window.CSAdapters || null; }

  var OTEL_JS = [
    "'use strict';",
    "/* dependency-free OTLP/HTTP trace exporter — generated by CodeSovereign",
    "   Engine.Observability (§7). Ships finished spans to a local OpenTelemetry",
    "   Collector. No npm dependency; OTLP/HTTP JSON is a documented wire format. */",
    "const http = require('http'); const https = require('https');",
    "const ENDPOINT = process.env.OTEL_EXPORTER_OTLP_ENDPOINT || 'http://localhost:4318';",
    "const SERVICE = process.env.OTEL_SERVICE_NAME || (require('../package.json').name || 'app');",
    "const ENABLED = process.env.OTEL_SDK_DISABLED !== 'true';",
    "let sent = 0, failed = 0;",
    "function hrNano(ms) { return String(Math.round(ms * 1e6)); }",
    "function toOtlp(trace) {",
    "  const spans = (trace.spans || []).map((s) => ({",
    "    traceId: (trace.id || '').padEnd(32, '0').slice(0, 32),",
    "    spanId: (String(s.start) + '0000').slice(-16),",
    "    name: s.name, kind: 1,",
    "    startTimeUnixNano: hrNano(s.start), endTimeUnixNano: hrNano(s.start + (s.ms || 0)),",
    "    attributes: [{ key: 'http.route', value: { stringValue: trace.path || '' } }, { key: 'http.method', value: { stringValue: trace.method || '' } }],",
    "    status: { code: (trace.status >= 500 ? 2 : 1) }",
    "  }));",
    "  return { resourceSpans: [{ resource: { attributes: [{ key: 'service.name', value: { stringValue: SERVICE } }] },",
    "    scopeSpans: [{ scope: { name: 'codesovereign' }, spans }] }] };",
    "}",
    "function exportTrace(trace) {",
    "  if (!ENABLED || !trace || !(trace.spans || []).length) return;",
    "  const body = Buffer.from(JSON.stringify(toOtlp(trace)));",
    "  const u = new URL(ENDPOINT.replace(/\\/$/, '') + '/v1/traces');",
    "  const lib = u.protocol === 'https:' ? https : http;",
    "  const req = lib.request(u, { method: 'POST', headers: { 'content-type': 'application/json', 'content-length': body.length }, timeout: 2000 }, (res) => {",
    "    res.resume(); if (res.statusCode >= 200 && res.statusCode < 300) sent++; else failed++;",
    "  });",
    "  req.on('error', () => { failed++; }); req.on('timeout', () => { req.destroy(); failed++; });",
    "  req.end(body);",
    "}",
    "module.exports = { exportTrace, stats: () => ({ sent, failed, endpoint: ENDPOINT, enabled: ENABLED }) };",
    ""
  ].join('\n');

  var COLLECTOR_YAML = [
    '# local OpenTelemetry Collector config — generated by CodeSovereign (§7)',
    '# run:  otelcol-contrib --config otel-collector-config.yaml',
    'receivers:',
    '  otlp:',
    '    protocols:',
    '      grpc: { endpoint: 0.0.0.0:4317 }',
    '      http: { endpoint: 0.0.0.0:4318 }',
    'processors:',
    '  batch: {}',
    'exporters:',
    '  file:',
    '    path: ./.sovereign/otel/collector-out.json',
    '  debug:',
    '    verbosity: normal',
    'service:',
    '  pipelines:',
    '    traces:  { receivers: [otlp], processors: [batch], exporters: [file, debug] }',
    '    metrics: { receivers: [otlp], processors: [batch], exporters: [file, debug] }',
    '    logs:    { receivers: [otlp], processors: [batch], exporters: [file, debug] }',
    ''
  ].join('\n');

  var COMPOSE_YAML = [
    '# local telemetry stack — no SaaS account (§7)',
    'services:',
    '  otel-collector:',
    '    image: otel/opentelemetry-collector-contrib:latest',
    '    command: ["--config=/etc/otelcol/config.yaml"]',
    '    volumes:',
    '      - ./otel-collector-config.yaml:/etc/otelcol/config.yaml:ro',
    '      - ./.sovereign/otel:/.sovereign/otel',
    '    ports: ["4317:4317", "4318:4318"]',
    ''
  ].join('\n');

  var SENTRY_JS = [
    "'use strict';",
    "/* optional self-hosted Sentry wiring — generated by CodeSovereign (§8).",
    "   Set SENTRY_DSN to a LOCAL Sentry (docker: getsentry/self-hosted). No",
    "   dependency is bundled; `npm i @sentry/node` to activate, otherwise this",
    "   is a no-op and the app's own logs/crashes/ capture remains the record. */",
    "let Sentry = null;",
    "try { if (process.env.SENTRY_DSN) Sentry = require('@sentry/node'); } catch (_) {}",
    "if (Sentry) { Sentry.init({ dsn: process.env.SENTRY_DSN, tracesSampleRate: 0.1, environment: process.env.NODE_ENV || 'development' }); }",
    "module.exports = {",
    "  capture: (err) => { if (Sentry) Sentry.captureException(err); },",
    "  active: () => !!Sentry,",
    "  probe: () => { const e = new Error('Sovereign crash probe'); if (Sentry) Sentry.captureException(e); return e; }",
    "};",
    ""
  ].join('\n');

  function files() {
    return { '/src/otel.js': OTEL_JS, '/otel-collector-config.yaml': COLLECTOR_YAML, '/otel-compose.yml': COMPOSE_YAML };
  }
  function sentryFiles() {
    return { '/src/sentry.js': SENTRY_JS, '/sentry/README.md': '# Local Sentry (optional)\n\n`getsentry/self-hosted` — https://github.com/getsentry/self-hosted\n\n```bash\ngit clone https://github.com/getsentry/self-hosted && cd self-hosted && ./install.sh\n# then set SENTRY_DSN to the local DSN and `npm i @sentry/node`\n```\n' };
  }

  function persist(res) {
    if (!S()) return;
    S().write('otel-evidence.json', {
      generatedAt: Date.now(), capability: 'observability', support: 'SUPPORTED',
      status: res.status, reason: res.reason || null, need: res.need || null,
      checks: res.checks || null, endpoint: res.endpoint || 'http://localhost:4318',
      localFallback: 'the app\'s own /debug/traces + /metrics + logs/crashes/ are the always-on local record',
      external: { HOSTED_SENTRY_EXPORT: 'BLOCKED_CREDENTIAL_REQUIRED' }
    });
  }

  function verify(opts) {
    opts = opts || {};
    var A = adapters();
    if (!A || !A.run) {
      var b = { status: 'BLOCKED', reason: 'RUNTIME_BRIDGE_UNAVAILABLE', need: 'the desktop app with a folder open' };
      persist(b); return Promise.resolve(b);
    }
    return Promise.resolve(A.run('otel', { endpoint: opts.endpoint || null })).then(function (r) {
      r = r || { status: 'FAIL', reason: 'ADAPTER_NO_RESULT' };
      persist(r); return r;
    }, function (e) { var f = { status: 'FAIL', reason: 'ADAPTER_ERROR', detail: String(e && e.message || e) }; persist(f); return f; });
  }

  function analyze() {
    if (!FS() || !has('/server.js')) {
      if (S()) S().write('otel-evidence.json', { generatedAt: Date.now(), present: false, capability: 'observability', support: 'SUPPORTED', note: 'no Node backend' });
      return { present: false };
    }
    var f = Object.assign({}, files(), sentryFiles());
    var wrote = [];
    Object.keys(f).forEach(function (p) { try { FS().write(p, f[p]); wrote.push(p); } catch (_) {} });
    var report = { generatedAt: Date.now(), present: true, capability: 'observability', support: 'SUPPORTED',
      status: 'GENERATED', wrote: wrote,
      note: 'OTLP exporter wired (src/otel.js); run the collector with `docker compose -f otel-compose.yml up` then Engine.Observability.verify()',
      localFallback: '/debug/traces + /metrics + logs/crashes/ are always on',
      external: { HOSTED_SENTRY_EXPORT: 'BLOCKED_CREDENTIAL_REQUIRED' } };
    if (S()) S().write('otel-evidence.json', report);
    return report;
  }

  function load() { try { var v = S() && S().read('otel-evidence.json'); return (v && typeof v === 'object') ? v : null; } catch (_) { return null; } }

  Engine.Observability = { files: files, sentryFiles: sentryFiles, verify: verify, analyze: analyze, load: load, OTEL_JS: OTEL_JS };
  console.info('[Observability] local OTel Collector + self-hosted Sentry adapters ready — Engine.Observability');
})();
